    log("\u68C0\u6D4B\u5230\u5DF2\u5B89\u88C5\u8FC7\u4E2D\u6587\u8865\u4E01\uFF0C\u5C06\u57FA\u4E8E\u539F\u7248\u5907\u4EFD\u91CD\u65B0\u6253\u8865\u4E01\u3002");
