    log(`\u8986\u76D6\u7387\uFF1A${stats.translated}/${stats.total}\uFF0C\u672A\u7FFB\u8BD1\u7684\u82F1\u6587\u6587\u672C ${Object.keys(missing).length} \u6761\u5DF2\u5199\u5165\uFF1A${UNTRANSLATED_PATH}`);
